<template>
  <div>
    <div v-if="canManage || (activeLiveSession && canJoinLive)" class="toolbar page-toolbar class-detail-toolbar"><div class="toolbar-actions"><button v-if="canManage && classStatusAction" class="button secondary" @click="changeClassStatus(classStatusAction.status)">{{ classStatusAction.label }}</button><button v-if="canManage" class="button secondary" @click="showScheduleForm = !showScheduleForm">{{ showScheduleForm ? 'Đóng lịch' : 'Lên lịch' }}</button><button v-if="activeLiveSession && canJoinLive" class="button secondary" @click="openLiveSession">{{ activeLiveSession.status === 1 || String(activeLiveSession.status).toLowerCase() === 'started' ? 'Vào phiên trực tuyến' : 'Mở phiên trực tuyến' }}</button><label v-if="canManage && !activeLiveSession" class="live-session-late-setting">Trễ sau <input v-model.number="liveLateAfterMinutes" type="number" min="0" max="240" aria-label="Số phút tính đi trễ" /> phút</label><button v-if="canManage && !activeLiveSession" class="button primary" @click="createSession" :disabled="busy || liveSessionsLoading">{{ busy ? 'Đang tạo…' : 'Tạo phiên trực tuyến' }}</button></div></div>
    <div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div>
    <section v-if="showScheduleForm && classInfo" class="panel" style="margin-bottom:16px"><form class="grid-two" @submit.prevent="createSchedule"><div class="form-field"><label>Bắt đầu</label><input v-model="scheduleForm.startsAt" class="form-input" type="datetime-local" required /></div><div class="form-field"><label>Kết thúc</label><input v-model="scheduleForm.endsAt" class="form-input" type="datetime-local" required /></div><div class="form-field"><label>Mã giảng viên</label><input v-model="scheduleForm.teacherId" class="form-input" required placeholder="Mã giáo viên đã phân công" /></div><div class="form-field"><label>Lặp lại</label><input v-model.trim="scheduleForm.recurrence" class="form-input" placeholder="Hàng tuần · tùy chọn" /></div><button class="button primary" :disabled="busy">Tạo lịch học</button></form></section>
    <div v-if="loading" class="loading-state">Đang tải lớp học…</div>
    <template v-else-if="classInfo">
      <div class="class-detail-layout"><main><div class="panel"><div class="class-context"><span>{{ teacherIds.length }} giáo viên được phân công · {{ formatDate(classInfo.startDate) }} – {{ formatDate(classInfo.endDate) }}</span><StatusPill :value="classInfo.status" :labels="classStatusLabels" /></div><div class="tab-controls"><RouterLink v-for="item in tabs" :key="item.key" class="tab-control" :class="{ active: activeTab === item.key }" :to="`/classes/${classInfo.id}/${item.route}`">{{ item.label }}</RouterLink></div>
        <div class="class-tab-content">
        <section v-if="activeTab === 'overview'" class="stack"><div class="grid-two"><div class="panel"><div class="panel-heading"><h2>Lịch học</h2><span>{{ schedules.length }}</span></div><div v-if="schedules.length" class="list-compact"><div v-for="schedule in schedules" :key="schedule.id" class="schedule-item"><div><strong>{{ scheduleLabel(schedule) }}</strong><span>{{ formatScheduleTime(schedule.startsAt) }}–{{ formatScheduleTime(schedule.endsAt) }} · {{ schedule.recurrence ? recurrenceLabel(schedule.recurrence) : 'Một lần' }}</span></div><div class="card-actions"><StatusPill :value="schedule.status" :labels="scheduleStatusLabels" /><button v-if="canManage && scheduleCanChange(schedule.status)" class="mini-button" @click="beginReschedule(schedule)">Đổi</button><button v-if="canManage && scheduleCanChange(schedule.status)" class="mini-button" @click="cancelSchedule(schedule)">Hủy</button></div><form v-if="editingScheduleId === schedule.id" class="inline-form schedule-edit" @submit.prevent="saveReschedule(schedule)"><input v-model="scheduleEdit.startsAt" class="form-input" type="datetime-local" required /><input v-model="scheduleEdit.endsAt" class="form-input" type="datetime-local" required /><input v-model.trim="scheduleEdit.recurrence" class="form-input" placeholder="Lặp lại" /><button class="mini-button" :disabled="busy">Lưu</button><button type="button" class="mini-button" @click="editingScheduleId = ''">Đóng</button></form></div></div><div v-else class="empty-state"><strong>Chưa có lịch</strong><span>Lịch học sẽ hiển thị khi được tạo.</span></div></div><div class="panel"><div class="panel-heading"><h2>Hoạt động</h2><span>{{ activities.length }}</span></div><div v-if="activities.length" class="list-compact"><RouterLink v-for="activity in activities" :key="activity.id" class="list-compact-item" :to="`/activities/${activity.id}`"><div><strong>{{ activity.title }}</strong><span>{{ enumLabel(activity.kind, enumLabels.activityKind) }} · {{ activity.dueAt ? formatDate(activity.dueAt) : 'Không có hạn' }}</span></div><StatusPill :value="activity.status" :labels="enumLabels.activityStatus" /></RouterLink></div><div v-else class="empty-state"><strong>Chưa có hoạt động</strong><span>Bài tập và bài thi phát hành cho lớp sẽ xuất hiện tại đây.</span></div></div></div></section>
        <section v-else-if="activeTab === 'content'" aria-label="Nội dung khóa học của lớp"><StudentClassContentPanel v-if="auth.role === 'student'" :class-id="classInfo.id" /><div v-else class="empty-state"><span>Chương trình học được quản lý trong không gian giảng viên.</span></div></section>
        <section v-else-if="activeTab === 'resources'" class="class-resources" aria-label="Tài nguyên của lớp"><div class="class-tab-toolbar"><span class="cell-subtle">{{ resources.length }} tài nguyên</span><button v-if="canManage" class="button secondary" @click="showResourceForm = !showResourceForm">{{ showResourceForm ? 'Đóng biểu mẫu' : 'Thêm tài nguyên' }}</button></div><form v-if="showResourceForm" class="stack resource-form" @submit.prevent="createResource"><div class="grid-two"><div class="form-field"><label>Tiêu đề</label><input v-model.trim="resourceForm.title" class="form-input" required maxlength="200" placeholder="Trang trình chiếu tuần 01" /></div><div class="form-field"><label>Loại</label><select v-model="resourceForm.type" class="form-select"><option value="Document">Tài liệu</option><option value="Slide">Trang trình chiếu</option><option value="Video">Video</option><option value="Attachment">Tệp đính kèm</option><option value="Recording">Bản ghi</option></select></div></div><div class="form-field"><label>Mô tả</label><textarea v-model.trim="resourceForm.description" class="form-textarea" maxlength="20000" placeholder="Mô tả ngắn"></textarea></div><div class="form-field"><label>URL ngoài (hoặc chọn tệp)</label><input v-model.trim="resourceForm.externalUrl" class="form-input" type="url" placeholder="https://…" /><input class="form-input" type="file" @change="onResourceFile" /></div><div v-if="resourceForm.type === 'Recording'" class="form-field"><label>Mã phiên trực tuyến</label><input v-model.trim="resourceForm.liveSessionId" class="form-input" placeholder="Chỉ dùng bản ghi của phiên đã kết thúc" /></div><button class="button primary" :disabled="resourceBusy">{{ resourceBusy ? 'Đang tạo…' : 'Lưu bản nháp' }}</button></form><ul v-if="resources.length" class="class-tab-list"><li v-for="resource in resources" :key="resource.id" class="class-tab-row"><a class="resource-link class-tab-copy" :href="resource.accessUrl || resource.externalUrl || undefined" target="_blank" rel="noreferrer"><strong>{{ resource.title }}</strong><span>{{ enumLabel(resource.type, enumLabels.resourceType) }} · {{ resource.description || 'Không có mô tả' }}</span></a><div class="card-actions"><StatusPill :value="resource.status" :labels="enumLabels.resourceStatus" /><button v-if="canManage && isResourceDraft(resource.status)" class="mini-button" @click="changeResourceStatus(resource)">Công bố</button><button v-else-if="canManage && isResourcePublished(resource.status)" class="mini-button" @click="changeResourceStatus(resource)">Lưu trữ</button></div></li></ul><div v-else class="empty-state"><strong>Chưa có tài nguyên</strong><span>Tài liệu được phát hành cho lớp sẽ xuất hiện tại đây.</span></div></section>
        <section v-else class="class-essays" aria-label="Danh sách bài tiểu luận">
          <ul v-if="essays.length" class="class-tab-list">
            <li v-for="essay in essays" :key="essay.id">
              <RouterLink class="class-tab-row" :to="auth.role === 'student' ? `/classes/${classInfo.id}/essays/${essay.id}` : '/essays'">
                <div class="class-tab-copy"><strong>{{ essay.title }}</strong><span>Hạn {{ essay.deadline ? formatDate(essay.deadline) : 'chưa đặt' }} · tối đa {{ essay.maxScore }} điểm</span></div>
                <StatusPill :value="essay.status" :labels="enumLabels.essayAssignmentStatus" />
              </RouterLink>
            </li>
          </ul>
          <div v-else class="empty-state"><strong>Chưa có tiểu luận</strong><span>Bài tiểu luận của lớp sẽ hiển thị tại đây.</span></div>
        </section>
        </div>
      </div></main><aside class="stack"><section class="panel"><div class="panel-heading"><h2>Điều hướng nhanh</h2></div><div class="list-compact"><RouterLink class="list-compact-item quick-nav-item" :to="`/activities?classId=${classInfo.id}`"><div class="quick-nav-copy"><strong>Bài tập & bài thi</strong><span class="quick-nav-description">Mở không gian đánh giá</span></div><span class="quick-nav-arrow" aria-hidden="true">→</span></RouterLink><RouterLink class="list-compact-item quick-nav-item" to="/gradebook"><div class="quick-nav-copy"><strong>Sổ điểm</strong><span class="quick-nav-description">Xem điểm theo lớp</span></div><span class="quick-nav-arrow" aria-hidden="true">→</span></RouterLink><RouterLink class="list-compact-item quick-nav-item" to="/progress"><div class="quick-nav-copy"><strong>Tiến độ</strong><span class="quick-nav-description">Trạng thái hoàn thành</span></div><span class="quick-nav-arrow" aria-hidden="true">→</span></RouterLink></div></section><section class="panel"><div class="panel-heading"><h2>Chỉ số nhanh</h2></div><div class="progress-row"><div class="progress-row-head"><span>Hoạt động phát hành</span><strong>{{ publishedActivities }}/{{ activities.length }}</strong></div><div class="progress-track"><div class="progress-fill" :style="{ width: `${activities.length ? publishedActivities / activities.length * 100 : 0}%` }"></div></div></div><div class="progress-row"><div class="progress-row-head"><span>Tài nguyên</span><strong>{{ resources.length }}</strong></div></div></section><section v-if="canManage" class="panel"><div class="panel-heading"><h2>Giảng viên</h2><span>{{ teacherIds.length }} được phân công</span></div><form class="inline-form" @submit.prevent="assignTeacher"><input v-model.trim="teacherFormId" class="form-input" required placeholder="Mã giảng viên" /><button class="mini-button">Thêm</button></form><div v-if="teacherIds.length" class="list-compact" style="margin-top:10px"><div v-for="teacherId in teacherIds" :key="teacherId" class="list-compact-item"><strong>{{ teacherId.slice(0, 8) }}</strong><button class="mini-button" @click="removeTeacher(teacherId)">Gỡ</button></div></div></section><section class="panel"><div class="panel-heading"><h2>Danh sách lớp</h2><span>{{ enrollments.length }} lượt ghi danh</span></div><form v-if="canManage" class="inline-form" @submit.prevent="enrollStudent"><input v-model.trim="studentFormId" class="form-input" required placeholder="Mã học viên" /><button class="mini-button">Ghi danh</button></form><div v-if="enrollments.length" class="list-compact" style="margin-top:10px"><div v-for="enrollment in enrollments.slice(0, 12)" :key="enrollment.id" class="list-compact-item"><div><strong>{{ enrollment.studentDisplayName || 'Học viên chưa có tên' }}</strong><span>{{ formatDateTime(enrollment.enrolledAt) }}</span></div><div class="card-actions"><StatusPill :value="enrollment.status" :labels="enumLabels.enrollmentStatus" /><button v-if="canManage && isEnrollmentActive(enrollment.status)" class="mini-button" @click="dropStudent(enrollment.studentId)">Xóa</button></div></div></div><div v-else class="empty-state"><strong>Danh sách lớp chưa tải</strong><span>Chỉ người có quyền danh sách lớp mới xem được danh sách.</span></div></section><section class="panel"><div class="panel-heading"><h2>Thông báo</h2><span>{{ announcements.length }}</span></div><form v-if="canManage" class="stack" @submit.prevent="createAnnouncement"><input v-model.trim="announcementForm.title" class="form-input" required placeholder="Tiêu đề" /><textarea v-model.trim="announcementForm.content" class="form-textarea" required placeholder="Nội dung thông báo"></textarea><button class="button secondary">Tạo bản nháp</button></form><div v-if="announcements.length" class="list-compact" style="margin-top:12px"><div v-for="announcement in announcements.slice(0, 4)" :key="announcement.id" class="list-compact-item"><div><strong>{{ announcement.title }}</strong><span>{{ announcement.content }}</span></div><div class="card-actions"><StatusPill :value="announcement.status" :labels="enumLabels.announcementStatus" /><button v-if="canManage && isAnnouncementDraft(announcement.status)" class="mini-button" @click="publishAnnouncement(announcement)">Công bố</button><button v-else-if="canManage && isAnnouncementPublished(announcement.status)" class="mini-button" @click="archiveAnnouncement(announcement)">Lưu trữ</button></div></div></div></section></aside></div>
    </template>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import StudentClassContentPanel from '../../learning/components/StudentClassContentPanel.vue'; import { academicsApi, assessmentApi, classroomApi, essayApi, learningApi, communicationApi } from '../../../shared/api/client'; import { errorMessage } from '../../../shared/api/http'; import { enumLabels, enumLabel, formatDate, formatDateTime, type AssessmentActivity, type EssayAssignment, type LearningClass, type LiveSession, type Resource, type Schedule } from '../../../shared/types'; import { useAuthStore } from '../../../shared/stores/auth'; import { useNavigationStore } from '../../../shared/stores/navigation'
type Enrollment = { id: string; studentId: string; studentDisplayName?: string; status: string | number; enrolledAt: string }; type Announcement = { id: string; title: string; content: string; status: string | number }
const classStatusLabels = ['Đang chuẩn bị', 'Đang mở', 'Tạm dừng', 'Đã hoàn thành', 'Đã lưu trữ']
const scheduleStatusLabels = ['Đã lên lịch', 'Đã đổi lịch', 'Tạm ngưng', 'Đã hoàn thành']
const route = useRoute(); const router = useRouter(); const auth = useAuthStore(); const navigation = useNavigationStore(); const classInfo = ref<LearningClass | null>(null); const teacherIds = ref<string[]>([]); const schedules = ref<Schedule[]>([]); const liveSessions = ref<LiveSession[]>([]); const liveSessionsLoading = ref(true); const activities = ref<AssessmentActivity[]>([]); const essays = ref<EssayAssignment[]>([]); const resources = ref<Resource[]>([]); const enrollments = ref<Enrollment[]>([]); const announcements = ref<Announcement[]>([]); const loading = ref(true); const busy = ref(false); const resourceBusy = ref(false); const error = ref(''); const showScheduleForm = ref(false); const showResourceForm = ref(false); const editingScheduleId = ref(''); const liveLateAfterMinutes = ref(15); const activeTab = computed<'overview'|'content'|'resources'|'essays'>(() => route.name === 'class-content' ? 'content' : route.name === 'class-resources' ? 'resources' : route.name === 'class-essays' ? 'essays' : 'overview'); const tabs = [{ key: 'overview', label: 'Tổng quan', route: 'overview' }, { key: 'content', label: 'Nội dung khóa học', route: 'content' }, { key: 'resources', label: 'Tài nguyên', route: 'resources' }, { key: 'essays', label: 'Tiểu luận', route: 'essays' }] as const; const scheduleForm = reactive({ teacherId: '', startsAt: '', endsAt: '', recurrence: '' }); const scheduleEdit = reactive({ startsAt: '', endsAt: '', recurrence: '' }); const resourceForm = reactive({ title: '', description: '', type: 'Document', externalUrl: '', liveSessionId: '', file: null as File | null }); const announcementForm = reactive({ title: '', content: '' }); const teacherFormId = ref(''); const studentFormId = ref(''); const canManage = computed(() => auth.has('classroom.session.manage') || auth.has('academics.classes.manage')); const canJoinLive = computed(() => auth.has('classroom.session.join')); const activeLiveSession = computed(() => liveSessions.value[0] || null); const classStatusAction = computed(() => { const status = typeof classInfo.value?.status === 'number' ? classInfo.value.status : String(classInfo.value?.status).toLowerCase(); if (status === 0 || status === 'preparing') return { label: 'Mở lớp', status: 'Active' }; if (status === 1 || status === 'active') return { label: 'Tạm dừng', status: 'Paused' }; if (status === 2 || status === 'paused') return { label: 'Tiếp tục', status: 'Active' }; if (status === 3 || status === 'completed') return { label: 'Lưu trữ', status: 'Archived' }; return null }); const publishedActivities = computed(() => activities.value.filter(item => ['Published', 'Open', 'InProgress', 1, 2].includes(item.status as never)).length)
async function load() { loading.value = true; liveSessionsLoading.value = true; error.value = ''; const id = String(route.params.classId); const results = await Promise.allSettled([academicsApi.classDetail(id), academicsApi.schedules(id), classroomApi.sessions(id), assessmentApi.activities(id), essayApi.assignments(id), learningApi.resources(id), academicsApi.enrollments(id), communicationApi.announcements(id)]); if (results[0].status === 'fulfilled') { classInfo.value = results[0].value.class; teacherIds.value = results[0].value.teacherIds; scheduleForm.teacherId ||= teacherIds.value[0] || ''; navigation.renameTab(route.fullPath, classInfo.value.code, `${classInfo.value.code} · ${classInfo.value.name}`) } if (results[1].status === 'fulfilled') schedules.value = results[1].value; if (results[2].status === 'fulfilled') liveSessions.value = results[2].value; liveSessionsLoading.value = false; if (results[3].status === 'fulfilled') activities.value = results[3].value; if (results[4].status === 'fulfilled') essays.value = results[4].value; if (results[5].status === 'fulfilled') resources.value = results[5].value; if (results[6].status === 'fulfilled') enrollments.value = results[6].value; if (results[7].status === 'fulfilled') announcements.value = results[7].value as Announcement[]; if (results[0].status === 'rejected') error.value = 'Không tải được chi tiết lớp học.'; loading.value = false }
function toIso(value: string) { return value ? new Date(value).toISOString() : value }
function toDateTimeInput(value: string) { const date = new Date(value); if (Number.isNaN(date.getTime())) return ''; const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000); return local.toISOString().slice(0, 16) }
function formatScheduleTime(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}` }
function formatScheduleDate(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : `${String(date.getDate()).padStart(2, '0')}/${String(date.getMonth() + 1).padStart(2, '0')}/${date.getFullYear()}` }
function scheduleLabel(schedule: Schedule) {
  const date = new Date(schedule.startsAt)
  if (Number.isNaN(date.getTime())) return 'Buổi học chưa xác định'
  const weekdays = ['Chủ nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7']
  const hour = date.getHours()
  const period = hour < 12 ? 'Buổi sáng' : hour < 18 ? 'Buổi chiều' : 'Buổi tối'
  return `${weekdays[date.getDay()]} · ${formatScheduleDate(schedule.startsAt)} · ${period}`
}
function recurrenceLabel(value: string) {
  const normalized = value.toUpperCase().replace(/\s+/g, '')
  if (normalized.includes('DAILY')) return 'Hàng ngày'
  if (normalized.includes('MONTHLY')) return 'Hàng tháng'
  if (normalized.includes('WEEKLY')) {
    const days = normalized.match(/BYDAY=([^;]+)/)?.[1]?.split(',').map(day => ({ MO: 'T2', TU: 'T3', WE: 'T4', TH: 'T5', FR: 'T6', SA: 'T7', SU: 'CN' } as Record<string, string>)[day]).filter(Boolean)
    return days?.length ? `Hàng tuần · ${days.join(', ')}` : 'Hàng tuần'
  }
  return 'Lặp lại'
}
function scheduleCanChange(status: string | number) { return status === 0 || status === 1 || ['scheduled', 'rescheduled'].includes(String(status).toLowerCase()) }
function isSchedulable(status: string | number) { return scheduleCanChange(status) }
function openLiveSession() { if (activeLiveSession.value) router.push(`/classes/${route.params.classId}/live/${activeLiveSession.value.id}`) }
function beginReschedule(schedule: Schedule) { editingScheduleId.value = schedule.id; scheduleEdit.startsAt = toDateTimeInput(schedule.startsAt); scheduleEdit.endsAt = toDateTimeInput(schedule.endsAt); scheduleEdit.recurrence = schedule.recurrence || '' }
async function saveReschedule(schedule: Schedule) { if (!classInfo.value) return; busy.value = true; try { const updated = await academicsApi.reschedule(classInfo.value.id, schedule.id, { startsAt: toIso(scheduleEdit.startsAt), endsAt: toIso(scheduleEdit.endsAt), recurrence: scheduleEdit.recurrence || undefined }); const index = schedules.value.findIndex(item => item.id === schedule.id); if (index >= 0) schedules.value[index] = updated; editingScheduleId.value = '' } catch (cause) { error.value = errorMessage(cause) || 'Không đổi được lịch học.' } finally { busy.value = false } }
async function cancelSchedule(schedule: Schedule) { if (!classInfo.value || !window.confirm('Hủy buổi học này?')) return; busy.value = true; try { await academicsApi.cancelSchedule(classInfo.value.id, schedule.id); schedule.status = 'Cancelled' } catch (cause) { error.value = errorMessage(cause) || 'Không hủy được lịch học.' } finally { busy.value = false } }
async function changeClassStatus(status: string) { if (!classInfo.value) return; busy.value = true; try { classInfo.value = await academicsApi.changeClassStatus(classInfo.value.id, status) } catch (cause) { error.value = errorMessage(cause) || 'Không cập nhật được trạng thái lớp.' } finally { busy.value = false } }
async function assignTeacher() { if (!classInfo.value || !teacherFormId.value) return; try { await academicsApi.assignTeacher(classInfo.value.id, teacherFormId.value); if (!teacherIds.value.includes(teacherFormId.value)) teacherIds.value.push(teacherFormId.value); teacherFormId.value = '' } catch (cause) { error.value = errorMessage(cause) || 'Không phân công được giáo viên.' } }
async function removeTeacher(teacherId: string) { if (!classInfo.value || !window.confirm('Gỡ giáo viên khỏi lớp?')) return; try { await academicsApi.removeTeacher(classInfo.value.id, teacherId); teacherIds.value = teacherIds.value.filter(id => id !== teacherId) } catch (cause) { error.value = errorMessage(cause) || 'Không gỡ được giáo viên.' } }
function isEnrollmentActive(status: string | number) { return status === 0 || String(status).toLowerCase() === 'active' }
async function enrollStudent() { if (!classInfo.value || !studentFormId.value) return; try { await academicsApi.enrollStudent(classInfo.value.id, studentFormId.value); enrollments.value = await academicsApi.enrollments(classInfo.value.id); studentFormId.value = '' } catch (cause) { error.value = errorMessage(cause) || 'Không ghi danh được học viên.' } }
async function dropStudent(studentId: string) { if (!classInfo.value || !window.confirm('Xóa học viên khỏi lớp?')) return; try { await academicsApi.dropStudent(classInfo.value.id, studentId); const item = enrollments.value.find(value => value.studentId === studentId); if (item) item.status = 'Dropped' } catch (cause) { error.value = errorMessage(cause) || 'Không xóa được học viên.' } }
async function createSchedule() { if (!classInfo.value) return; busy.value = true; try { const created = await academicsApi.createSchedule(classInfo.value.id, { teacherId: scheduleForm.teacherId, startsAt: toIso(scheduleForm.startsAt), endsAt: toIso(scheduleForm.endsAt), recurrence: scheduleForm.recurrence || undefined }); schedules.value.push(created); showScheduleForm.value = false } catch (cause) { error.value = errorMessage(cause) || 'Không tạo được lịch học.' } finally { busy.value = false } }
function isResourceDraft(status: string | number) { return status === 0 || String(status).toLowerCase() === 'draft' }
function isResourcePublished(status: string | number) { return status === 1 || String(status).toLowerCase() === 'published' }
function onResourceFile(event: Event) { const input = event.target as HTMLInputElement; resourceForm.file = input.files?.[0] || null; if (resourceForm.file) resourceForm.externalUrl = '' }
async function createResource() {
  if (!classInfo.value || (!resourceForm.file && !resourceForm.externalUrl)) { error.value = 'Thêm URL hoặc chọn một tệp tài nguyên.'; return }
  resourceBusy.value = true
  try {
    const created = resourceForm.file
      ? await learningApi.uploadResource(classInfo.value.id, resourceForm.file, { title: resourceForm.title, description: resourceForm.description || undefined, type: resourceForm.type, liveSessionId: resourceForm.liveSessionId || undefined })
      : await learningApi.createResource(classInfo.value.id, { title: resourceForm.title, description: resourceForm.description || undefined, type: resourceForm.type, externalUrl: resourceForm.externalUrl, liveSessionId: resourceForm.liveSessionId || undefined })
    resources.value.unshift(created)
    Object.assign(resourceForm, { title: '', description: '', type: 'Document', externalUrl: '', liveSessionId: '', file: null })
    showResourceForm.value = false
  } catch (cause) { error.value = errorMessage(cause) || 'Không tạo được tài nguyên.' } finally { resourceBusy.value = false }
}
async function changeResourceStatus(resource: Resource) {
  try {
    const updated = isResourceDraft(resource.status) ? await learningApi.publishResource(resource.id) : await learningApi.archiveResource(resource.id)
    const index = resources.value.findIndex(item => item.id === resource.id)
    if (index >= 0) resources.value[index] = updated
  } catch (cause) { error.value = errorMessage(cause) || 'Không cập nhật được trạng thái tài nguyên.' }
}
async function createAnnouncement() { if (!classInfo.value) return; try { const announcement = await communicationApi.createAnnouncement(classInfo.value.id, announcementForm) as Announcement; announcements.value.unshift(announcement); announcementForm.title = ''; announcementForm.content = '' } catch (cause) { error.value = errorMessage(cause) || 'Không tạo được thông báo.' } }
function isAnnouncementDraft(status: string | number) { return status === 0 || String(status).toLowerCase() === 'draft' }
function isAnnouncementPublished(status: string | number) { return status === 1 || String(status).toLowerCase() === 'published' }
async function publishAnnouncement(announcement: Announcement) { try { const updated = await communicationApi.publishAnnouncement(announcement.id) as Announcement; Object.assign(announcement, updated) } catch (cause) { error.value = errorMessage(cause) || 'Không công bố được thông báo.' } }
async function archiveAnnouncement(announcement: Announcement) { try { const updated = await communicationApi.archiveAnnouncement(announcement.id) as Announcement; Object.assign(announcement, updated) } catch (cause) { error.value = errorMessage(cause) || 'Không lưu trữ được thông báo.' } }
async function createSession() { if (!classInfo.value) return; if (activeLiveSession.value) { openLiveSession(); return } const teacherId = auth.account?.id && teacherIds.value.includes(auth.account.id) ? auth.account.id : teacherIds.value[0]; if (!teacherId) { error.value = 'Lớp chưa có giáo viên được phân công.'; return } const schedule = schedules.value.filter(item => item.teacherId === teacherId && isSchedulable(item.status)).sort((left, right) => new Date(left.startsAt).getTime() - new Date(right.startsAt).getTime())[0]; busy.value = true; try { const session = await classroomApi.createSession(classInfo.value.id, { teacherId, lateAfterMinutes: liveLateAfterMinutes.value, ...(schedule ? { classScheduleId: schedule.id } : {}) }); await router.push(`/classes/${classInfo.value.id}/live/${session.id}`) } catch (cause) { error.value = errorMessage(cause) || 'Không tạo được phiên trực tuyến.' } finally { busy.value = false } }
onMounted(load)
</script>
